messages.content:
Tool response:
Tool: find_available_tutors
Description: Find Available Tutors
Parameters:
    {
      "type": "object",
      "properties": {
        "subject_name": {
          "type": "string",
          "description": "Name of the subject to filter tutors by (e.g., 'AP Calculus BC')",
          "title": "Subject Name"
        },
        "credential_verified": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter tutors by credential verification status (1 for verified, 0 for unverified)",
          "title": "Credential Verified"
        },
        "min_hourly_rate": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum hourly rate filter",
          "title": "Min Hourly Rate"
        },
        "max_hourly_rate": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum hourly rate filter",
          "title": "Max Hourly Rate"
        },
        "start_time": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Start time for availability slot search (ISO format)",
          "title": "Start Time"
        },
        "end_time": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "End time for availability slot search (ISO format)",
          "title": "End Time"
        },
        "days_of_week": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Comma-separated list of day numbers (1=Monday, 7=Sunday) to filter availability slots",
          "title": "Days Of Week"
        }
      },
      "required": [
        "subject_name"
      ]
    }
